// SPDX-License-Identifier: MIT
pragma solidity 0.6.12;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/PieShare.sol";

contract PieShareBlacklistTest is Test {
    PieShare token;
    address owner = address(0x1);
    address alice = address(0x2);
    address bob = address(0x3);

    function setUp() public {
        vm.startPrank(owner);
        token = new PieShare();
        // Exclude Alice and Bob from fees (owner already excluded in constructor)
        token.excludeFromFees(alice, true);
        token.excludeFromFees(bob, true);
        // Transfer tokens to Alice for testing
        token.transfer(alice, 100 ether);
        vm.stopPrank();
    }

    function testBlacklistBlocksTransfers() public {
        // Pre-blacklist transfer succeeds
        vm.prank(alice);
        token.transfer(bob, 10 ether);
        assertEq(token.balanceOf(bob), 10 ether, "Bob should have tokens");

        // Owner blacklists Alice
        vm.prank(owner);
        token.blacklistAddress(alice, true);

        // Post-blacklist transfer should fail with "Blacklisted address"
        vm.prank(alice);
        vm.expectRevert(bytes("Blacklisted address"));
        token.transfer(bob, 10 ether);
        assertEq(token.balanceOf(bob), 10 ether, "Bob's balance shouldn't change");
    }
}
```
